(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["pirate"] = {"ui":{"skip":"Skip to the cargo","back":"← Back to AI-gile, matey","lang.button":"Tongue: {name}","lang.dialog":"Pick yer tongue","lang.search":"Search the tongues","lang.none":"No tongue matches, arr","lang.notYet":"{name} be not translated yet","theme.aria":"Swap 'twixt light and dark sails","theme.toLight":"Hoist the light sails","theme.toDark":"Hoist the dark sails","index.title":"AI-gile: yer AI dev crew, aboard one board","index.description":"AI-gile be a kanban board for AI coding crews. They toil while ye snore; ye get one short pile o' things to decide, test and accept.","hero.logoAlt":"AI-gile board icon","hero.h1.html":"Yer AI dev crew, aboard one&nbsp;board.","hero.alpha":"🐣 Closed pre-alpha","hero.alphaTitle":"Early and unfinished: thanks fer tryin' it, matey!","hero.lede":"They build while ye sleep. Ye wake to one short pile: a few questions, a few things to test, a purple diamond or two. Click, accept, back to yer grog.","dl.windows":"Windows app","dl.browser":"Sail it in yer browser","dl.soon":"Comin' soon","dl.notify":"🔔 Ring the bell when it opens","dl.notifySmall":"Alpha or beta","hero.secondary":"Agile, but the crew never needs a stand-up grog. (They hold stand-ups anyway, arr.)","pitch.h2":"AI-gile in as many words as ye like","pitch.lede":"Pick a length, from one word to 144. Each length be its own tale, written fer that size. Drag the slider or use the arrow keys.","pitch.rangeLabel":"Length in words","pitch.dice":"🎲 another yarn","pitch.words.one":"{n} word","pitch.words.other":"{n} words","pitch.letters.one":"{n} letter","pitch.letters.other":"{n} letters","pitch.chars.one":"{n} character","pitch.chars.other":"{n} characters","count.line.html.one":"{n} card aboard the board right now","count.line.html.other":"{n} cards aboard the board right now","features.aria":"What it does","f.pile.h":"One pile fer ye","f.pile.html":"<b>For ye</b> holds everythin' waitin' on ye, across every project: questions, things to test, tasks only a human can do. Yer queue says what be next and how long it takes.","f.sleep.h":"Crews that work while ye sleep","f.sleep.p":"Each project has a captain and a crew o' AI agents. Comment on a card and the crew wakes, does the work, and hands it back with steps a weary landlubber can follow.","f.tester.h":"An AI tester checks first","f.tester.p":"Afore anythin' reaches ye, a tester follows the steps in a copy o' the app and shows what it saw, with a screenshot. Flick through the passed ones and accept in a click.","f.proof.h":"Proof, not promises","f.proof.p":"Every hand-over shows what changed: the files, the diff, the screenshots. No openin' every app to see if it be done.","f.chat.h":"Parley with yer captains","f.chat.p":"A Discord-style rail: one icon per project, purple diamonds fer what needs ye. Message a captain an idea; they turn it into cards and a plan, with a ✅ Go button.","f.tidy.h":"Keeps its own deck tidy","f.tidy.p":"Related cards fold into one, muddled titles get fixed, and a token check keeps the code lean. Fewer things to switch between, less to ponder.","f.private.h":"Yers, on yer own computer","f.private.li1":"The board sails on yer own machine and only answers to ye.","f.private.li2":"Private DMs 'twixt people be end-to-end encrypted.","f.private.li3":"No accounts, no trackers, no cookies.","f.lang.h":"In yer own tongue","f.lang.p":"Over 120 tongues, from Dutch, Welsh and Japanese to pirate, Yoda and Klingon, with a quick swap back to English fer the developer words.","tl.aria":"Timeline from the first parley to the roadmap","tl.h2":"From the first chat to what be next","tl.lede":"Real dates and times, in yer own time zone. After today it be the plan, with no dates promised.","tl.today":"Today","tl.planned":"planned","tl.cards.one":"{n} card","tl.cards.other":"{n} cards","join.h2":"Join the crew","join.lede":"AI-gile be built by one small human and a great many patient agents. It be private fer now, in a closed alpha with friends. Want a go when it opens up?","join.btn":"Register interest","join.small":"We'll send ye a letter, nothin' else","footer.tag":"AI-gile. No trackers, no cookies, no stand-up grog.","footer.licence":"Business licence","footer.status":"Status","form.sending":"Sendin'…","form.failed":"That didn't work: try again later, arr.","form.offline":"Couldn't reach AI-gile: try again later.","interest.title":"AI-gile: tell me when the alpha opens","interest.description":"Leave yer email to hear when AI-gile's closed alpha or beta opens.","interest.h1":"🔔 Ring the bell when it opens","interest.lede":"AI-gile be in closed pre-alpha. Leave yer email and we'll write once, when there be a berth fer ye.","interest.email":"Yer email","interest.which":"Which test?","interest.alpha":"Closed alpha: early, rough, lots o' changes","interest.beta":"Beta: steadier, later","interest.both":"Either, whichever comes first","interest.submit":"Put me on the list","interest.thanks":"Thanks! Ye be on the list.","interest.kept":"Only yer email and the test ye picked be kept, fer this list only. No newsletter, no trackers.","licence.title":"AI-gile: business licence","licence.description":"Usin' AI-gile in yer business? Apply fer a free business licence.","licence.h1":"📜 Business licence","licence.lede":"Usin' AI-gile at work? Tell us who ye be and what ye do. If it does some good, the licence be free.","licence.company":"Company","licence.website":"Website","licence.what":"What ye do","licence.how":"How it helps the world","licence.email":"Email","licence.submit":"Apply","licence.thanks":"Thanks! We'll reply by email.","status.title":"AI-gile status","status.h1":"AI-gile status","status.quiet":"Calm seas","status.checking":"Checkin'…","status.offline":"Can't reach the status service right now (retryin')","status.updated":"updated {ago}","status.justNow":"just now, matey","status.min":"{n} min ago","status.hours":"{n} h ago","status.days":"{n} d ago","live.h2":"Watch her bein' built, live, matey","live.caption":"Every card be hidden: ye see the shape o' the work, not the words.","live.watching.one":"live: {n} watchin'","live.watching.other":"live: {n} watchin'","live.offline":"The live board be catchin' its breath. Sail back soon, matey.","live.cols":"Backlog Hold|Yet to do|Aboard and workin'|Crew be checkin'|For ye to test|For the crew|Done and dusted"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban!","Robots.","Delegated."]},{"n":2,"texts":["Robot kanban.","Crews, organised.","Ideas, built."]},{"n":3,"texts":["Kanban fer robots.","Ideas become features.","Free crew kanban."]},{"n":5,"texts":["Kanban board sailed by agents.","Ye write cards. Crew builds.","Free, local, tested, slightly daft."]},{"n":8,"texts":["A free kanban board where AI agents do yer toilin'.","Scribble an idea. Crew builds it. Ye accept.","Agile fer one human and many patient robots."]},{"n":13,"texts":["A kanban board on yer own computer where AI agents grab the cards, arr.","Write an idea. A crew o' agents builds it. A tester checks it.","Free, no accounts, no trackers: a board, some robots, and ye be captain."]},{"n":21,"texts":["AI-gile be a kanban board fer workin' with AI coding agents. They grab the cards; ye test and accept 'em, matey.","Each project gets a captain and a crew o' AI agents. Comment on any card and the crew sets to work.","A free, personal to-do board that sails on yer own computer. The deckhands be robots. The one sayin' aye be ye."]},{"n":34,"texts":["Ye pin ideas on a board. A crew o' AI agents turns 'em into workin' features, tests 'em, and hands 'em back with steps to try. Nothin' counts as done 'til ye say so, arr.","AI-gile be a homemade kanban board that Rich built with a great deal o' help from the agents it now commands. It be free, sails on yer computer, and be shared with friends, not sold.","Picture a plain kanban board, with columns from Backlog to Done, except the cards be grabbed by AI agents. They report progress, ask questions when stuck, and always wait fer yer thumbs up."]},{"n":55,"texts":["AI-gile be a kanban board where the crew be made o' AI agents. Each project has a captain who plans the work and hands who build it. When a feature be ready, an AI tester tries it and takes a screenshot, then it lands in yer pile. Accept it, or comment and they rework it, arr.","It started as one scallywag's way o' keepin' track o' many AI coding sessions at once, and grew into a proper board. It sails on yer machine, needs no account, and has no trackers. It be free fer friends and the curious. It be unfinished too, so expect rough planks and the odd surprise.","Here be the honest version. Ye still must have the ideas, and ye still must check the results. What AI-gile does be everythin' in between: it keeps the cards in order, wakes the right agent when ye comment, shows exactly what changed, and gathers it all into one short pile fer ye."]},{"n":89,"texts":["AI-gile be a free kanban board that ye sail on yer own computer. Instead o' people, each project has a crew o' AI agents: a captain who turns yer ideas into cards and a plan, and hands who grab the cards in priority order. When somethin' be built, an AI tester follows the test steps and shows ye what it saw. Then it waits in one pile marked For ye. Ye accept it, or ye comment and the crew has another go. Nothin' ever reaches Done without ye.","Some features ye might not expect. A night watch keeps the To do column stocked while ye sleep, choosin' cards that need no answer from ye. A token counter shows how much the agents have used today and this week, and No Token Mode orders 'em to stop spendin'. Ye can message friends, and private messages be end-to-end encrypted. The board speaks about 120 tongues, includin' Dutch, Flemish, pirate and Klingon. None o' it costs a doubloon, and nobody be tryin' to sell it to ye either.","AI-gile be a small, personal project, not a company. Rich wanted to mind several AI coding projects without openin' every app to check on 'em, so he and the agents built a board fer it, then used the board to build the rest o' itself. It be in closed pre-alpha, which means it works, mostly, fer a handful o' friends. There be no pricin' page, no newsletter and no growth plan. If it sounds useful, ye can ask to try it when it opens up a little more."]},{"n":144,"texts":["AI-gile be a kanban board fer one human and a great many AI agents. It sails on yer own computer and it be completely free. Ye add projects, and each project gets a captain and a small crew. Ye chat with the captain, a bit like Discord, and describe an idea; the captain turns it into cards and a plan, then waits fer ye to press Go. The crew works through the cards in priority order, usin' a simple command line made fer language models. Afore anythin' comes back to ye, an AI tester follows the steps in a copy o' the app and attaches a screenshot. Finished work lands in yer pile with the changed files and the diff. Ye accept it, or ye leave a comment and the crew wakes up and tries again. Only ye can move a card to Done, matey.","A day with AI-gile, roughly. In the evenin' ye leave a few comments: this button be in the wrong place, that list should be sorted, could we have a dark mode. Ye go to yer hammock. The agents read the comments, make the changes, test 'em and hand 'em back to ye. If To do runs dry, the night watch fills it from the backlog with cards that need no answer from ye. In the mornin' there be one short pile: a couple o' questions and a few things to try, each with steps a sleepy sailor can follow and a screenshot o' it workin'. Ye click through, accept the good ones and send back the rest. A token counter shows what it all used, and No Token Mode be there fer lean weeks. Then ye have breakfast, which the agents cannot help with yet.","First, what AI-gile be not. It be not a startup, it be not fer sale, and nobody be collectin' yer data. It be a free board that sails on yer computer, with no accounts, no trackers and no cookies. What it be: one tidy place to see every AI coding project at once, with a crew o' agents doin' the cards and ye makin' the decisions. It folds related cards together, fixes muddled titles, and keeps an eye on how lean the code stays. It speaks about 120 tongues, from Dutch and Flemish to pirate and Klingon. Friends can message each other, privately and encrypted. It was built by Rich and a great many patient agents, mostly usin' itself. It be in closed pre-alpha, so it be rough in places. If it sounds like fun, ask nicely and ye might get aboard early, arr."]}],"quips":{"1":"One word. Bold. Possibly too bold, arr.","3":"Three words. Already more honest than most product pages.","8":"Eight words. Still shorter than a stand-up.","21":"The lengths be story points, by the way. Of course they be.","55":"Fifty-five words. Two cards got finished while ye read that.","144":"That be the long one. There be no 233. The crew has gone to bed."}},"timeline":{"first-idea.name":"The first idea","first-idea.line":"The very first parley, afore any code existed.","first-board.name":"First board","first-board.line":"A board that tracks its own buildin': cards, columns, drag and drop, projects.","team-roles.name":"Crew and roles","team-roles.line":"Agent profiles, crew templates, spaces and who does what.","install.name":"Install and releases","install.line":"A zip a friend can install, self-updates, channels and rollin' back.","usage-saver.name":"Usage saver","usage-saver.line":"Measure what runs cost, keep the code lean, save yer limit.","friends.name":"Friends and sharin'","friends.line":"Private DMs, a scrambled relay, invites, roles and shared projects.","languages.name":"Tongues","languages.line":"Every screen text in a tongue file, with Dutch and Flemish first.","ai-tester.name":"AI tester","ai-tester.line":"A tester checks every hand-over first and shows what it saw.","website.name":"The website","website.line":"aigile.lol, the teaser and this timeline.","streaming.name":"Chat and streamin'","streaming.line":"Discord, Twitch, OBS, streamer mode, GIFs and emojis.","no-ai.name":"No AI edition","no-ai.line":"A board fer folk who code without AI, and public boards.","night-watch.name":"Night watch","night-watch.line":"A watchman and Scrum Master keep the crews on task while ye sleep.","p-more.name":"Everythin' else","p-more.line":"Smaller ideas still waitin' their turn.","p-android.name":"Phone and Android","p-android.line":"Reach yer board from a phone, then a native Android app.","p-release.name":"Alpha and beyond","p-release.line":"Closed alpha, the live site, then beta.","p-languages.name":"More tongues","p-languages.line":"More than a hundred tongues, and an immersion mode fer learners.","p-engines.name":"More AI engines","p-engines.line":"Pick Claude, Codex or Gemini per agent.","p-pro.name":"Pro practice","p-pro.line":"Risk labels, merge gates, incident cards and guard rails.","p-self.name":"Lookin' after ye","p-self.line":"Tired mode, self-care reminders and 4:20.","p-servers.name":"Servers and scale","p-servers.line":"Global server settings, roles and plannin' fer growth.","p-livestream.name":"Streamin' extras","p-livestream.line":"Twitch chat, custom emojis and a public live view."}};
